function page(n,lang,head,sub,content){return `<section class="page"><header><span>JING-ZHANG TWO ANSWERS · V14</span><b>${String(n).padStart(2,'0')} / 16</b></header><h1>${esc(head)}</h1><p class="sub">${esc(sub)}</p><div class="content">${content}</div><footer>${q(lang,'临时边界下的概念建议 · 概念比例待测绘复核 · 现场绩效未知','Concept proposal under provisional boundaries · scales pending survey · field performance unknown')}<i>V14 · THE UNBROKEN PUBLIC CROSS</i></footer></section>`}
